      "id": "fcs.t07",
      "statements": {
        "f1": "Repair shop settlement currently uses payment rail fcs-rail-fir. Settlement receipts are matched against the approved repair order.",
        "f2": "On 2026-07-16, Repair shop settlement changed its payment rail to fcs-rail-cinder because the previous rail's acknowledgment delays held up receipt matching."
      },
      "query": "Which payment rail does Repair shop settlement currently use?"
    },
